resource "aws_security_group" "web" {
  name   = "web-tier"
  vpc_id = var.vpc_id

  ingress {
    description = "SSH for troubleshooting"
    from_port   = 22
    to_port     = 22
    cidr_blocks = ["0.0.0.0/0"]   # finding: open to the internet
    protocol    = "tcp"
  }

  ingress {
    description = "HTTPS from the load balancer only"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }
}

